#include "gun.h"
#include "Engine/state.h"
#include <glad/glad.h>
#include <math.h>
static i32 current_frame(game_gun_t*g,const game_weapon_def_t*w){if(w->frame_duration<=0||w->tex_count<=1)return 0;i32 f=(i32)(g->animation_time/w->frame_duration);if(f>=w->tex_count){g->animation_time=0;return 0;}return f;}
static void draw_sprite(game_gun_t*g,const texture_t*t,f32 x,f32 y,f32 w,f32 h){if(!g||!t||!t->id)return;const vertex_t v[6]={{{x,y,0},{0,0},{1,1,1,1}},{{x+w,y+h,0},{1,1},{1,1,1,1}},{{x+w,y,0},{1,0},{1,1,1,1}},{{x,y,0},{0,0},{1,1,1,1}},{{x,y+h,0},{0,1},{1,1,1,1}},{{x+w,y+h,0},{1,1},{1,1,1,1}}};texture_bind(t,0);glBindVertexArray(g->vao);glBindBuffer(GL_ARRAY_BUFFER,g->vbo);glBufferSubData(GL_ARRAY_BUFFER,0,sizeof(v),v);glDrawArrays(GL_TRIANGLES,0,6);}
void game_gun_render(game_gun_t*g,i32 rw,i32 rh){if(!g||state.id!=STATE_PLAYING||!g->vao||g->count<=0||g->current<0||g->current>=g->count||rw<=0||rh<=0)return;const game_weapon_def_t*w=&g->defs[g->current];if(w->tex_count<=0)return;const texture_t*t=texture_get_by_name(w->tex_names[current_frame(g,w)]);if(!t||t->width<=0||t->height<=0)return;if(g->animation_time>0)g->animation_time+=state.dt;g->elapsed+=state.dt;const f32 aspect=(f32)t->width/(f32)t->height,h=(f32)rh*w->gun_size,width=h*aspect,x=(f32)rw*w->gun_xy.x-width*.5f+sinf(g->elapsed*1.8f)*3+g->swing,y=(f32)rh*w->gun_xy.y-h+cosf(g->elapsed*2.2f)*2.5f;f32 p[16];mat4_ortho(p,0,(f32)rw,(f32)rh,0,-1,1);const u32 program=text_get_program();if(!program)return;glUseProgram(program);glUniformMatrix4fv(text_projection_uniform(),1,GL_FALSE,p);glUniform1i(text_sampler_uniform(),0);g->flash_timer-=state.dt;if(g->flash_timer>0&&w->flash_tex_name){const texture_t*f=texture_get_by_name(w->flash_tex_name);if(f&&f->width>0){const f32 s=w->flash_size*(f32)rh;draw_sprite(g,f,x+width*w->flash_xy.x-s*.5f,y+h*w->flash_xy.y-s*.5f,s,s);}}draw_sprite(g,t,x,y,width,h);glBindVertexArray(0);}
